1	type Cell = [number, number]; // [x, y]
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [0, -1], [0, 1],
6	  [1, -1], [1, 0], [1, 1],
7	];
8	
9	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const cellOf = (key: string): Cell => {
12	  const [x, y] = key.split(",").map(Number);
13	  return [x, y];
14	};
15	
16	export function nextGeneration(cells: Cell[]): Cell[] {
17	  const alive = new Set(cells.map(keyOf));
18	  const neighborCounts = new Map<string, number>();
19	
20	  for (const [x, y] of cells) {
21	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
22	      const neighbor = keyOf([x + dx, y + dy]);
23	      neighborCounts.set(neighbor, (neighborCounts.get(neighbor) ?? 0) + 1);
24	    }
25	  }
26	
27	  const isAliveNextGen = (key: string, count: number): boolean =>
28	    count === 3 || (count === 2 && alive.has(key));
29	
30	  return [...neighborCounts]
31	    .filter(([key, count]) => isAliveNextGen(key, count))
32	    .map(([key]) => cellOf(key));
33	}
